import sys
import random

#Manual implementation of Extended Euclidean Algorithm
#Find gcd(a, b) and coefficients x, y such that ax + by = gcd(a, b)
def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    else:
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y


#Modular multiplicative inverse
def mod_inverse(a, m):
    gcd, x, y = extended_gcd(a, m)
    if gcd != 1:
        raise Exception("Modular inverse does not exist")
    else:
        return (x % m + m) % m


#Miller–Rabin primality test
def miller_rabin(n, rounds=5):  
    if n <= 3:
        return n == 2 or n == 3
    if n % 2 == 0:
        return False

    #Write n-1 as 2^s * d
    s = 0
    d = n - 1
    while d % 2 == 0:
        d //= 2
        s += 1

    for i in range(rounds):
        a = random.randrange(2, n - 1)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for j in range(s - 1):
            x = pow(x, 2, n)
            if x == 1:
                return False
            if x == n - 1:
                break
        else:
            return False
    return True





def encrypt(message, e, n):
    #Convert message to int
    message_bytes = message.encode('utf-8')
    message_int = int.from_bytes(message_bytes, byteorder='big')
    if message_int >= n:
        raise ValueError("Message too large for the given key size")
    
    encrypted = pow(message_int, e, n)
    return encrypted



def decrypt(ciphertext, d, n):
    decrypted_int = pow(ciphertext, d, n)
    
    #Convert int back to bytes and to string
    byte_length = (decrypted_int.bit_length() + 7) // 8
    decrypted_bytes = decrypted_int.to_bytes(byte_length, byteorder='big')
    return decrypted_bytes.decode('utf-8')





def scope():
    if len(sys.argv) != 4:
        print("Usage: ./exe p1 p2 m")
        sys.exit(1)
        
    p = int(sys.argv[1])
    q = int(sys.argv[2])
    message = sys.argv[3]
    
    if p != 2*q + 1:
        print(f"Error: p must equal 2q + 1. Got p={p}, q={q}, 2q+1={2*q+1}")
        sys.exit(1)
    
    #Verify p and q are prime
    if not miller_rabin(p) or not miller_rabin(q):
        print("Error: p and q must be prime")
        sys.exit(1)
    
    #Calculate n and totient
    n = p * q
    totient = (p - 1) * (q - 1)
    
    #Choose e such that 1 < e < totient and gcd(e, totient) = 1
    e = 65537
    gcd, x, y = extended_gcd(e, totient)
    #If e = 65537 (standard) doesn't work, find another e
    if gcd != 1:
        for candidate in range(3, 100000, 2):
            gcd, x, y = extended_gcd(candidate, totient)
            if gcd == 1:
                e = candidate
                break
    
    # Calculate d (modular multiplicative inverse of e mod totient)
    d = mod_inverse(e, totient)
    encrypted = encrypt(message, e, n)
    decrypted = decrypt(encrypted, d, n)
    
    # Output results
    print(f"E: {e}")
    print(f"D: {d}")
    print(f"Message: {message}")
    print(f"Encoded message: {encrypted}")
    print(f"Decoded message: {decrypted}")


scope()

